"""Minimum Window Substring — sliding window with a "missing" counter.

`missing` tracks how many required characters are still unmatched. When it hits
zero the window is valid, so shrink from the left while it stays valid.

Time: O(|s| + |t|)   Space: O(|t|)
"""
from collections import Counter


class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not s or not t or len(t) > len(s):
            return ""
        need = Counter(t)
        missing = len(t)
        best = (float("inf"), 0, 0)
        left = 0
        for right, ch in enumerate(s):
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1
            while missing == 0:
                if right - left + 1 < best[0]:
                    best = (right - left + 1, left, right)
                need[s[left]] += 1
                if need[s[left]] > 0:
                    missing += 1
                left += 1
        return "" if best[0] == float("inf") else s[best[1]:best[2] + 1]
